document.querySelectorAll('.nav-research').forEach(group=>{const button=group.querySelector('button');const set=open=>{group.classList.toggle('is-open',open);button.setAttribute('aria-expanded',String(open))};group.addEventListener('mouseenter',()=>set(true));group.addEventListener('mouseleave',()=>{if(!group.contains(document.activeElement))set(false)});button.addEventListener('click',()=>set(true));group.addEventListener('focusin',()=>set(true));group.addEventListener('focusout',e=>{if(!group.contains(e.relatedTarget))set(false)});group.addEventListener('keydown',e=>{if(e.key==='Escape'){button.focus();set(false)}if(e.key==='ArrowDown'&&e.target===button){e.preventDefault();set(true);group.querySelector('a').focus()}});document.addEventListener('pointerdown',e=>{if(!group.contains(e.target))set(false)})});
